<?php $title='Tugas Saya';$page='tasks';$pdo=Database::connection();$u=current_user();$q=$pdo->prepare('SELECT t.*,m.title module_title,s.id submission_id,s.score,s.feedback,s.answer_text FROM tasks t JOIN modules m ON m.id=t.module_id JOIN classes c ON c.id=m.class_id LEFT JOIN submissions s ON s.task_id=t.id AND s.student_id=? WHERE c.name=? ORDER BY t.created_at DESC');$q->execute([$u['id'],$u['class_name']]);$rows=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Tugas Saya</h1><p>Kumpulkan jawaban dan pantau status penilaian.</p></div></div><div class="card-grid"><?php foreach($rows as $r): ?><article class="course-card"><span><?= e($r['module_title']) ?></span><h3><?= e($r['title']) ?></h3><p><?= nl2br(e($r['description'])) ?></p><small>Deadline: <?= e($r['deadline']??'Tidak ditentukan') ?></small><form class="submit-task-form form-grid" data-task="<?= $r['id'] ?>" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="task_id" value="<?= $r['id'] ?>"><label>Jawaban<textarea name="answer_text" rows="4"><?= e($r['answer_text']??'') ?></textarea></label><label>Lampiran (opsional)<input type="file" name="attachment" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.zip,.txt,.jpg,.jpeg,.png"><small class="muted">Maksimal 10 MB. Isi jawaban atau lampirkan file.</small></label><button class="btn btn-primary btn-small">Kumpulkan</button></form><?php if($r['score']!==null): ?><div class="notice success">Nilai: <b><?= e($r['score']) ?></b> · <?= e($r['feedback']) ?></div><?php elseif($r['submission_id']): ?><span class="badge warning">Sudah dikumpulkan · Menunggu penilaian</span><?php endif; ?></article><?php endforeach; ?></div><?php if(!$rows): ?><div class="panel empty-state">Belum ada tugas untuk kelas Anda.</div><?php endif; ?><?php require __DIR__.'/../_dashboard_end.php'; ?>